207		if pv.ReservedTotal != 20 || pv.SpentTotal != 0 {
208			t.Fatalf("policy totals = %+v", pv)
209		}
210	
211		// 账本：一条预留（资金）+ 一条批准（状态）。
212		var reserve, approval bool
213		for _, e := range w.Ledger() {
214			switch e.Kind {
215			case LedgerReserve:
216				reserve = true
217				if e.AccountID != "payer" || e.Amount != 20 || e.RequestID != "r1" {
218					t.Fatalf("reserve entry = %+v", e)
219				}
220			case LedgerApproval:
221				approval = true
222				if e.AccountID != "u1" || e.Amount != 0 || e.RequestID != "r1" {
223					t.Fatalf("approval entry = %+v", e)
224				}
225			}
226		}
227		if !reserve || !approval {
228			t.Fatalf("ledger missing reserve=%v approval=%v", reserve, approval)
229		}
230	
231		// 批准后可正常结算。
232		if _, err := w.Settle("u1", "r1", 8); err != nil {
233			t.Fatal(err)
234		}
235		bal, _ = w.Balance("payer")
236		if bal != (Balances{Available: 92, Reserved: 0}) {
237			t.Fatalf("balance after settle = %+v, want {92 0}", bal)
238		}
239	}
