332	func TestApproveQuotaRecheck(t *testing.T) {
333		w, c := setupApproval(t)
334		// 门槛 10、累计上限 50：直接预留费用 ≤ 10，待审批费用 > 10。
335		p := approvalPolicy(c)
336		p.ID = "p-quota"
337		if err := w.SavePolicy(p); err != nil {
338			t.Fatal(err)
339		}
340		apply := func(rid string, fee int64) RequestView {
341			in := approvalApply()
342			in.PolicyID = "p-quota"
343			in.RequestID = rid
344			in.EstimatedFee = fee
345			req, err := w.Apply(in)
346			if err != nil {
347				t.Fatal(err)
348			}
349			return req
350		}
351		// 第一笔直接预留 10，占用累计额度 10。
352		if r := apply("r-a", 10); r.State != RequestReserved {
353			t.Fatalf("fee 10 state = %v, want reserved", r.State)
354		}
355		// 第二笔 20 待审批（申请时 used=10，10+20=30 ≤ 50）。
356		if r := apply("r1", 20); r.State != RequestPendingApproval {
357			t.Fatalf("fee 20 state = %v, want pending", r.State)
358		}
359		// 第三笔 20 待审批（申请时 used 仍为 10，10+20=30 ≤ 50）。
360		if r := apply("r3", 20); r.State != RequestPendingApproval {
361			t.Fatalf("fee 20 state = %v, want pending", r.State)
362		}
363		// 批准第二笔：used=10+20=30 ≤ 50，成功。
364		if _, err := w.Approve("u1", "r1", "sa", "dev-approve"); err != nil {
365			t.Fatalf("approve r1: %v", err)
366		}
367		pv, _ := w.Policy("p-quota")
368		if pv.ReservedTotal != 30 {
369			t.Fatalf("reserved total = %d, want 30", pv.ReservedTotal)
370		}
371		// 再预留一笔 10，used 升到 40。
372		if r := apply("r-b", 10); r.State != RequestReserved {
373			t.Fatalf("fee 10 state = %v, want reserved", r.State)
374		}
375		// 批准第三笔：40+20=60 > 50，拒绝批准并保留待审批。
376		if _, err := w.Approve("u1", "r3", "sa", "dev-approve"); !errors.Is(err, ErrQuotaExceeded) {
377			t.Fatalf("err = %v, want ErrQuotaExceeded", err)
378		}
379		req, _ := w.Request("u1", "r3")
380		if req.State != RequestPendingApproval {
381			t.Fatalf("state = %v, want still pending", req.State)
382		}
383		// 取消第一笔释放额度（used 降为 30）后，第三笔可批准。
384		if _, err := w.Cancel("u1", "r-a"); err != nil {
385			t.Fatal(err)
386		}
387		if _, err := w.Approve("u1", "r3", "sa", "dev-approve"); err != nil {
388			t.Fatalf("approve after quota freed: %v", err)
389		}
390	}
