233				t.Fatalf("%s approver = %q", rid, req.ApproverAccountID)
234			}
235			// 拒绝信息说明策略被停用并包含停用理由。
236			if req.RejectReason == "" || !strings.Contains(req.RejectReason, "fraud suspected") || !strings.Contains(req.RejectReason, "deactivat") {
237				t.Fatalf("%s reject reason = %q", rid, req.RejectReason)
238			}
239		}
240		// 已预留请求保持预留。
241		r3, _ := w.Request("u1", "r3")
242		if r3.State != RequestReserved {
243			t.Fatalf("reserved request state = %v", r3.State)
244		}
245	
246		// 不冻结、不占用、不退款：只有 r3 的 8 处于预留。
247		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 92, Reserved: 8}) {
248			t.Fatalf("balance = %+v, want {92 8}", bal)
249		}
250		got, _ := w.Policy("p-approval")
251		if got.ReservedTotal != 8 || got.SpentTotal != 0 {
252			t.Fatalf("totals = reserved %d spent %d, want 8/0", got.ReservedTotal, got.SpentTotal)
253		}
254	
255		// 账本：1 条停用（出资账户）+ 2 条拒绝（使用账户，各带请求号），金额均为零。
256		deacts, rejs := 0, 0
257		for _, e := range w.Ledger() {
258			switch e.Kind {
259			case LedgerPolicyDeactivation:
260				deacts++
261				if e.AccountID != "payer" || e.Amount != 0 {
262					t.Fatalf("deactivation entry = %+v", e)
263				}
264			case LedgerRejection:
265				if e.RequestID == "r1" || e.RequestID == "r2" {
266					rejs++
267					if e.AccountID != "u1" || e.Amount != 0 || !strings.Contains(e.Reason, "fraud suspected") {
268						t.Fatalf("rejection entry = %+v", e)
269					}
270				}
271			}
272		}
273		if deacts != 1 || rejs != 2 {
274			t.Fatalf("deactivations = %d rejections = %d, want 1/2", deacts, rejs)
275		}
276		// 使用账户账本按账户可核对到两条拒绝。
277		if n := countKind(w.AccountLedger("u1"), LedgerRejection); n != 2 {
278			t.Fatalf("u1 rejection entries = %d, want 2", n)
279		}
280	
281		// 已预留请求仍可结算或取消。
282		if _, err := w.Settle("u1", "r3", 3); err != nil {
283			t.Fatalf("settle reserved after deactivation: %v", err)
284		}
285		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 97, Reserved: 0}) {
286			t.Fatalf("balance after settle = %+v, want {97 0}", bal)
287		}
288	}
